export const membersListQueryKey = (options?: Options<MembersListData>) => createQueryKey('membersList', options);

/**
 * Lists the firm's members — display name, status, the roles held, and whether a professional profile has been written. Deactivated members are included: they still hold matters. Not paged; a firm's roster is bounded by its headcount rather than by its activity.
 */
export const membersListOptions = (options?: Options<MembersListData>) => queryOptions<MembersListResponse, MembersListError, MembersListResponse, ReturnType<typeof membersListQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await membersList({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: membersListQueryKey(options)
});

/**
 * Invites a member into the session firm: creates the (unverified, account-less) user, enqueues the per-firm member.provision outbox row, audits the invite — one atomic batch — then sends the activation email (a password-reset link; the reset creates the credential).
 */
export const membersInviteMutation = (options?: Partial<Options<MembersInviteData>>): MutationOptions<MembersInviteResponse, MembersInviteError, Options<MembersInviteData>> => {
    const mutationOptions: MutationOptions<MembersInviteResponse, MembersInviteError, Options<MembersInviteData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await membersInvite({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

export const rolesListQueryKey = (options?: Options<RolesListData>) => createQueryKey('rolesList', options);

/**
 * Lists the firm's roles: what each one is called, the permissions it carries, and how many active members hold it. The reference a person consults before granting one — a role name alone says nothing about what it lets somebody do.
 */
export const rolesListOptions = (options?: Options<RolesListData>) => queryOptions<RolesListResponse, RolesListError, RolesListResponse, ReturnType<typeof rolesListQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await rolesList({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: rolesListQueryKey(options)
});

/**
 * Sets the roles a member holds, as a whole set. Refused when the actor is the subject, when the set names a sub-role without its parent role or two sub-roles of one parent, and when the change would leave the firm with no active member who can administer its members. Returns the roles held after the write.
 */
export const membersSetRolesMutation = (options?: Partial<Options<MembersSetRolesData>>): MutationOptions<MembersSetRolesResponse, MembersSetRolesError, Options<MembersSetRolesData>> => {
    const mutationOptions: MutationOptions<MembersSetRolesResponse, MembersSetRolesError, Options<MembersSetRolesData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await membersSetRoles({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Deactivates a member: their sessions stop resolving to any capability, and their rows stay. A deactivated member is still the responsible attorney on the matters they carried and the author of what they filed, so the roster keeps listing them. Refused when the actor is the subject, and refused for the last member who can administer the firm.
 */
export const membersDeactivateMutation = (options?: Partial<Options<MembersDeactivateData>>): MutationOptions<MembersDeactivateResponse, MembersDeactivateError, Options<MembersDeactivateData>> => {
    const mutationOptions: MutationOptions<MembersDeactivateResponse, MembersDeactivateError, Options<MembersDeactivateData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await membersDeactivate({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Returns a deactivated member to active. They hold whatever roles they held when they left — deactivation suspends a member's access rather than stripping what they were given, so a return does not mean re-granting it by hand.
 */
export const membersReactivateMutation = (options?: Partial<Options<MembersReactivateData>>): MutationOptions<MembersReactivateResponse, MembersReactivateError, Options<MembersReactivateData>> => {
    const mutationOptions: MutationOptions<MembersReactivateResponse, MembersReactivateError, Options<MembersReactivateData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await membersReactivate({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

